// 검색 결과 → 번호 붙인 발췌. 저장소가 비면 빈 항목 하나가 오므로 document 가 있는 것만
const body = $('Question webhook').first().json.body;
const question = body.question;
const min = Number(body.min_score);
const min_score = body.min_score !== undefined && body.min_score !== null && Number.isFinite(min) ? min : 0.33;
const hits = $input.all()
  .filter(item => item.json.document)
  .map((item, i) => {
    const meta = item.json.document.metadata || {};
    return {
      n: i + 1,
      source: meta.source || '',
      title: meta.title || '',
      section: meta.section || '',
      score: Math.round((item.json.score ?? 0) * 1000) / 1000,
      text: item.json.document.pageContent,
    };
  });
const context = hits.map(h => `[${h.n}] ${h.text}`).join('\n\n');
return [{ json: {
  question,
  context,
  hits: hits.map(({ n, source, title, section, score }) => ({ n, source, title, section, score })),
  excerpts: hits.map(h => h.text),
  sources: [...new Set(hits.map(h => h.source))],
  top_score: hits.length ? hits[0].score : 0,
  min_score,
  relevant: hits.length > 0 && hits[0].score >= min_score,
} }];

// [번호] → [문서 제목], cited = 실제로 인용한 번호의 source. 범위 밖 번호는 버린다
const ctx = $('Build context').first().json;
const draft = String($json.output || '').trim();
const cited = [];
let answer = draft.replace(/\[(\d+)\]/g, (whole, num) => {
  const hit = ctx.hits[Number(num) - 1];
  if (!hit) return '';
  if (!cited.includes(hit.source)) cited.push(hit.source);
  return `[${hit.title}]`;
});
answer = answer.replace(/(\[[^\]]+\])(\s*\1)+/g, '$1').replace(/ +([.,])/g, '$1').trim();

// 답 검사 (규칙, LLM 아님): 하나라도 실패하면 사람에게 넘긴다
const excerpts = ctx.excerpts.join('\n');
const plain = answer.replace(/\[[^\]]*\]/g, '');
const squash = t => t.replace(/[\s.,!?·:;"'()\[\]\-]/g, '');
const NOT_FOUND = ['찾지 못했', '찾을 수 없', '포함되어 있지 않', '명시되어 있지 않', '언급이 없', '언급하고 있지 않',
  '언급되어 있지 않', '나와 있지 않', '내용은 없', '내용이 없', '규정에 없'];
const a = squash(plain), e = squash(excerpts);
const pairs = [];
for (let i = 0; i + 2 <= a.length; i++) pairs.push(a.slice(i, i + 2));
const overlap = pairs.length ? pairs.filter(p => e.includes(p)).length / pairs.length : 0;
// 질문에 나온 숫자(틀린 전제 "30일")를 답이 되짚는 것은 괜찮다
const allowed = new Set([...excerpts.matchAll(/\d+/g), ...ctx.question.matchAll(/\d+/g)].map(m => m[0]));
const numbers = [...plain.matchAll(/\d+/g)].map(m => m[0]);
const checks = [
  { name: 'found_in_policies', passed: !NOT_FOUND.some(w => plain.includes(w)) },
  { name: 'cites_excerpt', passed: cited.length >= 1 },
  { name: 'grounded', passed: overlap >= 0.3, overlap: Math.round(overlap * 100) / 100 },
  { name: 'numbers_from_policies', passed: numbers.every(n => allowed.has(n)), missing: numbers.filter(n => !allowed.has(n)) },
];
const failed = checks.filter(c => !c.passed).map(c => c.name);
const base = { sources: ctx.sources, top_score: ctx.top_score, checks, failed };
if (failed.length) {
  return [{ json: { route: '담당자 연결', answer: '규정에서 확실한 답을 찾지 못해 IT 담당자에게 전달했습니다.',
    draft: answer, cited: [], ...base } }];
}
return [{ json: { route: '자동 답변', answer, cited, ...base } }];
